import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.CcJ8wlZS.js";const u=JSON.parse('{"title":"CLI & Scripts Reference","description":"wf commands, note types, scripts, shared modules","frontmatter":{"type":"index","title":"CLI & Scripts Reference","description":"wf commands, note types, scripts, shared modules","created":"2026-09-19T00:00:00.000Z","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"cli.md","filePath":"cli.md"}'),r={name:"cli.md"};function a(s,t,i,n,l,p){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="cli-scripts-reference" tabindex="-1">CLI &amp; Scripts Reference <a class="header-anchor" href="#cli-scripts-reference" aria-label="Permalink to &quot;CLI &amp; Scripts Reference&quot;">​</a></h1><h2 id="note-types" tabindex="-1">Note Types <a class="header-anchor" href="#note-types" aria-label="Permalink to &quot;Note Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Location</th><th>Purpose</th></tr></thead><tbody><tr><td><code>source</code></td><td><code>evidence/sources/</code></td><td>Immutable bibliographic record + sha256</td></tr><tr><td><code>source-summary</code></td><td><code>evidence/source-summaries/</code></td><td>Faithful summary with locators, no inference</td></tr><tr><td><code>claim</code></td><td><code>evidence/claims/</code></td><td>Atomic assertion with <code>source_refs</code> (locator + quote) + <code>code_symbols</code> + <code>graph_edges</code></td></tr><tr><td><code>concept</code></td><td><code>concepts/</code> or <code>domains/&lt;d&gt;/concepts/</code></td><td>Stable explanation built ONLY from linked claims</td></tr><tr><td><code>experience-event</code></td><td><code>projects/&lt;p&gt;/experience-events/</code></td><td>Structured observation: problem → intervention → outcome</td></tr><tr><td><code>pattern</code></td><td><code>patterns/</code></td><td>Reusable context→problem→forces→solution (maturity 0–3)</td></tr><tr><td><code>anti-pattern</code></td><td><code>anti-patterns/</code></td><td>Repeated failure mode; detect and warn</td></tr><tr><td><code>skill</code></td><td><code>skills/</code></td><td>Reusable procedure with inputs/outputs</td></tr><tr><td><code>decision</code></td><td><code>projects/&lt;p&gt;/decisions/</code></td><td>ADR-like technical choice record</td></tr><tr><td><code>entity</code></td><td><code>global/entities/</code></td><td>Code-symbol index from AST parsing</td></tr><tr><td><code>change-set</code></td><td><code>evidence/traces/change-sets/</code></td><td>Agent-proposed edit batch for human review</td></tr><tr><td><code>synthesis</code></td><td><code>syntheses/</code></td><td>Query answer filed for reuse</td></tr></tbody></table><p><strong>See <code>schemas/frontmatter.md</code> for full contracts.</strong></p><hr><h2 id="cli-reference-wf" tabindex="-1">CLI Reference (<code>wf</code>) <a class="header-anchor" href="#cli-reference-wf" aria-label="Permalink to &quot;CLI Reference (`wf`)&quot;">​</a></h2><p>The <code>wf</code> command is the single entry point for controlling the fabric. It installs to <code>~/.local/bin/wf</code> (alias <code>wiki-fabric</code>).</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>wf install [--repo URL] [--dir DIR]</code></td><td>Clone + set up the fabric</td></tr><tr><td><code>wf update</code></td><td>Pull latest, rebuild entity index + catalog, lint, refresh installed CLI + project hooks</td></tr><tr><td><code>wf status</code></td><td>Fabric health + inventory counts</td></tr><tr><td><code>wf vault [PATH]</code></td><td>Create Obsidian vault (symlinks)</td></tr><tr><td><code>wf bootstrap &lt;project-path&gt;</code></td><td>Connect a project to the fabric</td></tr><tr><td><code>wf capture &lt;project-slug&gt; [--repo PATH]</code></td><td>Capture upstream repo docs → <code>evidence/raw/</code></td></tr><tr><td><code>wf capture &lt;project-slug&gt; --git &lt;owner/name-or-path&gt;</code></td><td>Capture PR/issue threads + high-signal commits → <code>evidence/raw/&lt;slug&gt;/git/</code> (add <code>--since 6m</code>, <code>--limit 30</code>, <code>--churn</code>)</td></tr><tr><td><code>wf ingest &lt;source&gt; [--extract-claims]</code></td><td>Ingest a source (LLM claim extraction)</td></tr><tr><td><code>wf query &quot;&lt;question&gt;&quot;</code></td><td>Ask the fabric a question</td></tr><tr><td><code>wf log --project &lt;slug&gt; ...</code></td><td>Log an experience event</td></tr><tr><td><code>wf hook {install|uninstall|status}</code></td><td>Git post-commit auto-capture+ingest (<code>--extract-claims</code> for LLM on drift)</td></tr><tr><td><code>wf claude {install|uninstall|status}</code></td><td>Managed always-on block in <code>AGENTS.md</code>/<code>CLAUDE.md</code> (<code>--user</code> for <code>~/.claude/CLAUDE.md</code>)</td></tr><tr><td><code>wf okf export --out DIR [--scope S]</code></td><td>Export the fabric as a deterministic portable OKF v0.2 bundle</td></tr><tr><td><code>wf okf import &lt;bundle&gt; [--scope S]</code></td><td>Ingest an external OKF bundle as immutable evidence (trust recorded, not inherited)</td></tr><tr><td><code>wf sync {init|status|push|pull}</code></td><td>Share the corpus with a team via a git remote</td></tr><tr><td><code>wf models ensure [--model ID] [--yes]</code></td><td>Check <code>llm.local_model</code> is cached; offer human-gated download (<code>--check</code> exits 0/1 without prompting)</td></tr><tr><td><code>wf lint [--okf] [--format json]</code></td><td>Deterministic linter (full profile; <code>--okf</code> = OKF conformance floor; JSON for CI)</td></tr></tbody></table><p>Environment: <code>WIKI_FABRIC_REPO</code> overrides the source repo URL.</p><hr><h2 id="scripts-reference" tabindex="-1">Scripts Reference <a class="header-anchor" href="#scripts-reference" aria-label="Permalink to &quot;Scripts Reference&quot;">​</a></h2><p>Pipeline scripts (each runs standalone: <code>python3 scripts/&lt;script&gt;.py --help</code>):</p><table tabindex="0"><thead><tr><th>Script</th><th>Purpose</th><th>LLM Cost</th></tr></thead><tbody><tr><td><code>ingest.py</code></td><td>Source → source record → claims (LLM extraction)</td><td>1 call per source</td></tr><tr><td><code>query.py</code></td><td>Question → evidence-backed answer</td><td>0 tokens (lexical + graph)</td></tr><tr><td><code>context.py</code></td><td>Task → scoped context manifest with reasons</td><td>0 tokens (deterministic)</td></tr><tr><td><code>lint.py</code></td><td>Deterministic checks (incl. <code>--okf</code> floor, <code>llm.local_model</code> validation)</td><td>0 tokens</td></tr><tr><td><code>eval.py</code></td><td>Golden-corpus evaluation</td><td>1 call per fixture</td></tr><tr><td><code>synthesize.py</code></td><td>Claims → concept pages (cloud or on-device route)</td><td>1 call per concept</td></tr><tr><td><code>log-experience.py</code></td><td>Capture experience event</td><td>0 tokens</td></tr><tr><td><code>mine-promotions.py</code></td><td>Cluster experience events → dossiers (honors <code>dossier</code> route)</td><td>0 tokens</td></tr><tr><td><code>promote.py</code></td><td>Manage promotion dossiers</td><td>0 tokens</td></tr><tr><td><code>rebuild-index.py</code></td><td>Rebuild registry index from files</td><td>0 tokens</td></tr><tr><td><code>propose-domains.py</code></td><td>Discover new domains from evidence</td><td>0 tokens</td></tr><tr><td><code>build-entity-index.py</code></td><td>AST entity index from source repos</td><td>0 tokens</td></tr><tr><td><code>graphify-bridge.py</code></td><td>Optional graphify integration (update/import/enrich/diff)</td><td>0 tokens</td></tr><tr><td><code>bootstrap-project.py</code></td><td>Connect new project to fabric</td><td>0 tokens</td></tr><tr><td><code>ensure-local-model.py</code></td><td>Check/download <code>llm.local_model</code> (<code>wf models ensure</code>)</td><td>0 tokens</td></tr><tr><td><code>bootstrap-fabric.sh</code></td><td>One-time global install</td><td>0 tokens</td></tr><tr><td><code>apply-changeset.sh</code></td><td>Apply a change-set to canonical pages</td><td>0 tokens</td></tr></tbody></table><p>Shared modules (imported by the scripts above; not entry points):</p><table tabindex="0"><thead><tr><th>Module</th><th>Purpose</th></tr></thead><tbody><tr><td><code>fabric_config.py</code></td><td>fabric.yaml loading (memoized), stage routing, actor conventions, local-model resolution/download</td></tr><tr><td><code>extract_backends.py</code></td><td>Claim-extraction layer: prompt building, 4 LLM backends (OpenAI-compatible/Anthropic/opencode/on-device), JSON repair, locator verification</td></tr><tr><td><code>local_llm.py</code></td><td>On-device generation: backend dispatch (GGUF via llama-cpp, MLX via mlx-lm), serialized model cache</td></tr><tr><td><code>wf_common.py</code></td><td>Shared helpers: <code>parse_frontmatter</code>, <code>norm</code>, <code>slugify</code>, hashing, timestamps</td></tr><tr><td><code>eval_core.py</code></td><td>Eval scoring primitives: <code>concept_match</code>, <code>jaccard</code>, <code>fuzzy_coverage</code>, <code>tokens</code></td></tr></tbody></table><hr><hr><h2 id="fabric-inventory" tabindex="-1">Fabric Inventory <a class="header-anchor" href="#fabric-inventory" aria-label="Permalink to &quot;Fabric Inventory&quot;">​</a></h2><p>Counts live in your fabric, not the repo. Check yours anytime:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>The repo ships only the harness — examples, templates, schemas, and scripts. Your claims, captures, and patterns accumulate locally as you connect projects.</p><hr>',22)])])}const m=e(r,[["render",a]]);export{u as __pageData,m as default};
